import * as console from "std/console";

function integrate(position: int, velocity: int, acceleration: int, ticks: int): int[] {
  let pos: int = position;
  let vel: int = velocity;
  let tick: int = 0;
  while (tick < ticks) {
    vel = vel + acceleration;
    pos = pos + vel;
    tick = tick + 1;
  }
  let result: int[] = [pos, vel];
  return result;
}

