function run(): int {
  let positions: int[] = [0, 10, -4];
  let velocities: int[] = [2, -1, 3];
  let ticks: int = 0;
  while (ticks < 3) {
    let i: int = 0;
    while (i < 3) {
      positions[i] = positions[i] + velocities[i];
      i = i + 1;
    }
    ticks = ticks + 1;
  }
  let checksum: int = 0;
  let j: int = 0;
  while (j < 3) {
    checksum = checksum + positions[j];
    j = j + 1;
  }
  return checksum;
}

