function transition(alive: boolean, neighbors: int): boolean {
  if (alive) {
    if (neighbors < 2) {
      return false;
    } else if (neighbors === 2 || neighbors === 3) {
      return true;
    } else {
      return false;
    }
  } else {
    if (neighbors === 3) {
      return true;
    } else {
      return false;
    }
  }
}

